function markDirty(){const button=document.getElementById('saveChanges');if(button){button.disabled=false;button.textContent='Save changes ↻'}}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function safeUrl(v=''){const s=String(v).trim();if(/^(https?:\/\/|mailto:|tel:|\/|\.\.?\/|#)/i.test(s))return s;if(/^(www\.)?[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+(?:[/:?#][^\s]*)?$/i.test(s))return`https://${s}`;return'#'}
function externalUrl(v='',domain=''){
 let s=String(v||'').trim();if(!s)return'';
 if(!/^[a-z][a-z0-9+.-]*:\/\//i.test(s))s=`https://${s.replace(/^\/+/,'')}`;
 try{const u=new URL(s);if(!['http:','https:'].includes(u.protocol))return'';if(domain==='github.com')u.pathname=u.pathname.replace(/\.git$/i,'');const host=u.hostname.toLowerCase().replace(/^www\./,'');return host===domain||host.endsWith(`.${domain}`)?u.href:''}catch{return''}
}
