function skillFallback(skill){const s=skill.toLowerCase();let paths;if(/^sql$|database|query/.test(s))paths='<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 1.7 3.6 3 8 3s8-1.3 8-3V5"/><path d="M4 12c0 1.7 3.6 3 8 3s8-1.3 8-3"/>';else if(/clean|quality|validation/.test(s))paths='<path d="m5 18 9-9"/><path d="m13 5 2-2 6 6-2 2"/><path d="m4 16 4 4"/><path d="M3 21h6"/>';else if(/\beda\b|exploratory|analytical|analysis|analytics/.test(s))paths='<path d="M4 19V5"/><path d="M4 19h16"/><path d="m7 15 3-4 3 2 5-7"/><circle cx="18" cy="6" r="1"/>';else if(/transform/.test(s))paths='<path d="M4 7h14l-3-3"/><path d="M20 17H6l3 3"/><path d="M18 7v4"/><path d="M6 17v-4"/>';else if(/etl|pipeline/.test(s))paths='<circle cx="5" cy="6" r="2"/><circle cx="19" cy="18" r="2"/><path d="M7 6h4a3 3 0 0 1 3 3v6a3 3 0 0 0 3 3h0"/><path d="m15 15 2 3-2 3"/>';else if(/model|engineering|architecture/.test(s))paths='<circle cx="12" cy="5" r="2"/><circle cx="5" cy="18" r="2"/><circle cx="19" cy="18" r="2"/><path d="m11 7-5 9m7-9 5 9M7 18h10"/>';else if(/problem|thinking/.test(s))paths='<path d="M9 18h6"/><path d="M10 22h4"/><path d="M8.2 14.5A7 7 0 1 1 15.8 14.5c-1 .8-1.4 1.6-1.6 3.5h-4.4c-.2-1.9-.6-2.7-1.6-3.5Z"/><path d="M12 7v4m0 3h.01"/>';else paths='<path d="m12 3 1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8L12 3Z"/><path d="m19 15 .9 2.1L22 18l-2.1.9L19 21l-.9-2.1L16 18l2.1-.9L19 15Z"/>';return`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths}</svg>`}
