 document.getElementById('projectsList').innerHTML=data.projects.length?data.projects.map((p,i)=>{const cover=safeImage(p.image);return `<article class="project-card"><div class="project-visual ${cover?'has-project-image':''}" ${cover?`style="background-image:linear-gradient(180deg,#172b2740,#172b2770),url('${cover}')"`:''}><div class="visual-top"><span>${esc((p.title||'PROJECT').toUpperCase())}</span><span>PROJECT ${i+1}</span></div>${!cover?'<div class="pipeline"><div class="layer raw"><small>1. PLAN</small><strong>Explore</strong><span>Understand</span><i>↓</i></div><div class="layer clean"><small>2. BUILD</small><strong>Develop</strong><span>Transform</span><i>↓</i></div><div class="layer gold"><small>3. SHARE</small><strong>Deliver</strong><span>Impact</span><i>✳</i></div></div>':`<div class="image-caption">${esc(p.imageAlt||p.title)}</div>`}<div class="visual-foot"><span>${esc((p.tags||[]).slice(0,3).join(' · ').toUpperCase())}</span><span>SELECTED PROJECT</span></div></div><div class="project-info"><div class="project-title"><div><p class="eyebrow">${esc(p.category||'PROJECT')}</p><h3>${esc(p.title)}</h3></div><span class="project-number">${i+1}.</span></div><p>${esc(p.description)}</p><div class="tags">${(p.tags||[]).map(t=>`<span>${esc(t.toUpperCase())}</span>`).join('')}</div>${p.link?`<a class="project-link" href="${esc(safeUrl(p.link))}" target="_blank" rel="noopener noreferrer">${esc(p.linkText||'View project')} <span>↗</span></a>`:''}</div></article>`}).join(''):'<p class="empty-state">No projects yet. Add your first project from Edit portfolio.</p>';
