  document.getElementById('contactDetails').innerHTML=info.length?info.map(([label,value,icon,url])=>`<div class="contact-detail"><span>${icon}</span><div><b>${esc(label)}</b>${url?`<a href="${esc(url)}">${esc(value)}</a>`:`<small>${esc(value)}</small>`}</div></div>`).join(''):'<p class="empty-state small">Add your contact details in Edit portfolio.</p>';
 const cvButtons=[document.getElementById('headerCV'),document.getElementById('heroCV')];cvButtons.forEach(a=>{a.href='#';a.removeAttribute('download');a.classList.remove('disabled');a.removeAttribute('aria-disabled')});
 document.getElementById('statProjects').textContent=String(data.projects.length);document.getElementById('statSkills').textContent=String(data.skills.length);document.getElementById('statExperience').textContent=String(data.experience.length);document.getElementById('statAvailability').textContent=data.availability||'Available';document.getElementById('copyright').textContent=`© ${new Date().getFullYear()} ${(data.name||'').toUpperCase()}`;
